package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices/all} — one place listing every invoice across all projects, oldest
 * first, each carrying the NAME of the project it belongs to and its lifecycle status so the
 * all-invoices page shows the project (not its id) and the stage it is at. Wired by
 * {@code officefloor/rest/api/invoices/all.GET.yml}. Joins {@link Invoice} against {@link Project}
 * server-side, mirroring {@link ProjectsGet} joining the client's name.
 *
 * <p>The list can grow huge, so it is served a page at a time: {@code page} (1-based, default 1)
 * and {@code size} (default 10) query parameters select the slice, and only that slice is fetched
 * from the database. The front-end's next/previous controls step {@code page}; the ordering stays
 * oldest-first so paging only windows the list, never reorders it.
 */
public class InvoicesAllGet {

    /** How many invoices a page shows when the client does not ask for a specific size. */
    private static final int DEFAULT_PAGE_SIZE = 10;

    public void service(@HttpQueryParameter("status") String status,
            @HttpQueryParameter("page") String page, @HttpQueryParameter("size") String size,
            InvoiceRepository invoices, ProjectRepository projects,
            ObjectResponse<List<InvoiceView>> response) {
        Map<Long, String> nameById = projects.findAllByOrderByIdAsc().stream()
                .collect(Collectors.toMap(Project::getId, Project::getName));
        String wanted = status == null ? null : status.trim();
        int pageNo = positiveOr(page, 1);
        int pageSize = positiveOr(size, DEFAULT_PAGE_SIZE);
        Pageable pageable = PageRequest.of(pageNo - 1, pageSize, Sort.by(Sort.Direction.ASC, "id"));
        List<Invoice> filtered = (wanted == null || wanted.isEmpty())
                ? invoices.findAll(pageable).getContent()
                : invoices.findByStatus(wanted, pageable).getContent();
        List<InvoiceView> views = filtered.stream()
                .map(i -> new InvoiceView(i.getId(), i.getProjectId(),
                        nameById.get(i.getProjectId()), i.getAmount(), i.getStatus(),
                        i.getIssuedDate(), i.getDueDate()))
                .collect(Collectors.toList());
        response.send(views);
    }
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { AllInvoicesToolbar } from '../../slots/defs/allInvoicesToolbar';
import { money } from '../../ui/money';

// An invoice as the all-invoices endpoint returns it: which project it is for (by NAME, joined
// server-side), its amount, and its lifecycle status (the stage it is at). See InvoicesAllGet.
export type InvoiceView = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

// One place listing every invoice across all projects, each row showing the project it is for and
// the stage it is at. Server data is read with useQuery under ['invoices', 'all'] — the key still
// starts with 'invoices', so a write that invalidates ['invoices'] refreshes this list too (rule 5).
export function AllInvoicesPage() {
  // The chosen stage lives in the URL (owned by features/invoices/statusFilter.slot.tsx). The page
  // reads the same key and asks the server for the narrowed list — a single source of truth, no
  // server data copied into state or filtered by hand. The key still starts with 'invoices', so a
  // write that invalidates ['invoices'] refreshes this list too (rule 5).
  const [status] = useSearchParam('invoiceStatus', asString);
  const invoices = useQuery({
    queryKey: ['invoices', 'all', status],
    queryFn: () =>
      getJson<InvoiceView[]>(
        status ? `/api/invoices/all?status=${encodeURIComponent(status)}` : '/api/invoices/all',
      ),
  });

  const rows = invoices.data ?? [];

  return (
    <section data-testid="all-invoices">
      <div data-testid="all-invoices-toolbar">
        <AllInvoicesToolbar.Slot />
      </div>
      {rows.length === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <table data-testid="all-invoices-table">
          <thead>
            <tr>
              <th>Project</th>
              <th>Amount</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((i) => (
              <tr key={i.id} data-testid={`invoice-row-${i.id}`}>
                <td data-testid="invoice-project">{i.projectName}</td>
                <td data-testid="invoice-amount">{money(Number(i.amount))}</td>
                <td data-testid="invoice-status">{i.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

